g=[[0,0,0,0,0,0,2,0,0,0,0,0,0,0],[0]*14,[8,8,8,8,0,8,8,8,8,8,8,8,8,8],[0]*14,[8,8,0,8,8,8,8,0,8,8,8,0,8,8],[0]*14,[0]*14,[8,8,0,8,8,8,8,8,8,0,8,8,8,8],[0]*14,[0]*14,[8,8,8,8,0,8,8,0,8,8,8,0,8,8],[0]*14,[0]*14,[0]*14,[0]*14]
from collections import deque
q=deque([(0,6)]); seen={(0,6)}
while q:
 r,c=q.popleft()
 for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]==0 and (nr,nc) not in seen:
   seen.add((nr,nc));q.append((nr,nc))
out=[[2 if (r,c) in seen else x for c,x in enumerate(row)] for r,row in enumerate(g)]
print(len(seen));print(out)
print('\n'.join(' '.join(map(str,row)) for row in out))

g=[[0]*14 for _ in range(15)]
g[0][6]=2
for r,vals in {2:[0,4],4:[2,7,11],7:[2,9],10:[4,7,11]}.items():
 for c in range(14):
  if c not in vals:g[r][c]=8
# apply rays interpretation: for each 8 stripe's holes, extend vertical red in those columns, horizontal connector immediately above stripe between extreme holes; a single hole spans full width
for r,holes in {2:[4],4:[2,7,11],7:[2,9],10:[4,7,11]}.items():
 if len(holes)==1: a,b=0,13
 else: a,b=min(holes),max(holes)
 rr=r-1
 for c in range(a,b+1):
  if g[rr][c]==0:g[rr][c]=2
 # paint verticals through gap columns from previous connector to this connector, bounded by adjacent stripe rows
 upper=({2:0,4:3,7:6,10:9}[r])
 lower=({2:1,4:3,7:6,10:14}[r])
 for c in holes:
  for y in range(upper,lower+1):
   if g[y][c]==0:g[y][c]=2
print('\n'.join(str(row) for row in g))

# Generate candidate along demonstrated stripe-hole propagation
G=[[0]*14 for _ in range(15)]
G[0][6]=2
for r,holes in [(2,[4]),(4,[2,7,11]),(7,[2,9]),(10,[4,7,11])]:
 for c in range(14):
  if c not in holes:G[r][c]=8
# connectors: for each stripe, preceding/following inter-row connector spans opening columns; seed row above first connects seed to opening.
# paint exact structures
for r,holes in [(2,[4]),(4,[2,7,11]),(7,[2,9]),(10,[4,7,11])]:
 for c in holes:G[r][c]=2
# at row1 link seed to first hole, row3 connect first row holes to following stripe's holes span; etc.
for rr,lo,hi in [(1,4,6),(3,2,11),(6,0,13),(9,2,11)]:
 for c in range(lo,hi+1):
  if G[rr][c]==0:G[rr][c]=2
# verticals through intervening blank rows at holes (below stripes)
for r,holes in [(2,[4]),(4,[2,7,11]),(7,[2,9]),(10,[4,7,11])]:
 end={2:3,4:6,7:9,10:14}[r]
 for c in holes:
  for y in range(r+1,end+1):
   if G[y][c]==0:G[y][c]=2
print(G)

g=[[0]*14 for _ in range(15)];g[0][6]=2
for r, holes in [(2,[4]),(4,[2,7,11]),(7,[2,9]),(10,[4,7,11])]:
 for c in range(14):
  if c not in holes:g[r][c]=8
# red route inferred: connector before first stripe links seed to its opening; subsequent connectors link next barrier openings.
for r, cols in [(1,range(4,7)),(3,range(2,12)),(6,range(14)),(9,range(2,12))]:
 for c in cols:g[r][c]=2
for r,holes,end in [(2,[4],3),(4,[2,7,11],6),(7,[2,9],9),(10,[4,7,11],14)]:
 for c in holes:
  for y in range(r+1,end+1):g[y][c]=2
print('\n'.join(str(row) for row in g))
